        $svg = $icons[$name] ?? ($icons['check'] ?? '');
        if ($extraClass !== '') {
            $svg = str_replace('class="iconoir-icon"', 'class="iconoir-icon ' . htmlspecialchars($extraClass, ENT_QUOTES, 'UTF-8') . '"', $svg);
        }
        if ($size !== null) {
            $s = (int)$size;
            $svg = preg_replace('/width="[^"]*"/', 'width="' . $s . '"', $svg, 1);
            $svg = preg_replace('/height="[^"]*"/', 'height="' . $s . '"', $svg, 1);
        }
        return $svg;
    }
}

if (!function_exists('iconoir_icon')) {
    function iconoir_icon($name, $extraClass = '', $size = null) {
        return iconoir($name, $extraClass, $size);
    }
}
